<template><section class="integration-table"><h3>{{ title }}</h3><div class="integration-toolbar"><label>Search identifiers / fields <input v-model="search" /></label><label>Sort <select v-model="sort"><option value="">Artifact order</option><template v-for="k in sortColumns" :key="k"><option :value="k">{{ k }} ↑</option><option :value="'-'+k">{{ k }} ↓</option></template></select></label><label v-if="candidate">Population <select v-model="selected"><option value="true">All Q95-and-ties candidates</option><option value="false">All eligible genes</option></select></label><label v-for="key in candidate?evidenceKeys:[]" :key="key">Min {{ key }} (%) <input v-model="filters[key]" type="number" min="0" max="100" step="1" /></label><a :href="download">Complete result CSV</a></div><p v-if="error" role="alert">{{ error }}</p><p v-else-if="!result">Loading full result index…</p><template v-else><p>{{ result.total }} records · page {{ page }}<span v-if="candidate"> · eligible={{ result.eligible_n }}, empirical Q95={{ number(result.threshold) }}</span></p><div class="integration-scroll"><table class="table compact-table"><thead><tr><th v-for="k in columns" :key="k">{{ k }}</th></tr></thead><tbody><tr v-for="(r,i) in result.items" :key="r.gene_id||r.transcript_id||i"><td v-for="k in columns" :key="k"><button v-if="['gene_id','transcript_id','entity_id'].includes(k)&&r[k]" class="ghost-link" @click="open(r,k)">{{ r[k] }}</button><span v-else>{{ value(r[k]) }}</span></td></tr></tbody></table></div><div class="integration-toolbar"><button class="btn subtle" :disabled="page===1" @click="page--">Previous records</button><button class="btn subtle" :disabled="page*50>=result.total" @click="page++">Next records</button></div></template></section></template>
<script setup>
import {ref,reactive,computed,watch,onMounted} from 'vue';import {integrationExport} from '../../api/integrationVisuals';import {integrationNumber as number} from '../../utils/integrationCharts'
const props=defineProps({context:Object,speciesId:String,tableId:String,title:String,candidate:Boolean});const emit=defineEmits(['entity']);const page=ref(1),search=ref(''),sort=ref(''),selected=ref('true'),result=ref(null),error=ref('');let seq=0
const evidenceKeys=['resource_percentile','GC_percentile','pI_percentile'],filters=reactive(Object.fromEntries(evidenceKeys.map(k=>[k,''])))
const evidenceParams=()=>Object.fromEntries(evidenceKeys.filter(k=>filters[k]!=='').map(k=>['min_'+k,Number(filters[k])/100]))
const columns=computed(()=>result.value?.items?.length?Object.keys(result.value.items[0]):[])
const sortColumns=computed(()=>columns.value.filter(k=>result.value?.items?.[0]?.[k]===null||typeof result.value?.items?.[0]?.[k]!=='object'))
const query=()=>({page:page.value,page_size:50,search:search.value,sort:sort.value||undefined,selected:selected.value,...evidenceParams()})
async function load(){const s=++seq,id=props.speciesId;try{const r=await props.context.get(props.candidate?'candidates/':`tables/${props.tableId}/`,query());if(s===seq&&id===props.speciesId){result.value=r;error.value=''}}catch(e){if(s===seq)error.value=e?.response?.data?.error?.message||e.message}}
watch([search,sort,selected,()=>JSON.stringify(filters)],()=>{page.value=1;load()});watch(page,load);watch(()=>props.context.manifest.value?.artifact_version,load);onMounted(load)
const download=computed(()=>integrationExport(props.speciesId,{...props.context.params(),kind:props.candidate?'candidates':'table',table_id:props.tableId,selected:selected.value,search:search.value,sort:sort.value,...evidenceParams()}))
function value(v){if(v===null||v===undefined)return '—';if(typeof v==='number')return number(v);return typeof v==='object'?JSON.stringify(v):String(v)}
function open(r,k){const entityType=k==='transcript_id'?'transcript':k==='entity_id'?r.entity_type||'gene':'gene';emit('entity',{...r,entity_type:entityType,entity_id:r[k],report_entity_key:r[k],[entityType+'_id']:r[k]})}
</script>
